import React from 'react';
import { Link } from 'react-router-dom';

const Navbar=()=>{

    return(
        <header className="flex justify-between items-center p-0">
        <nav className="flex items-center justify-between w-full bg-red-600 p-4 rounded-md">

            {/* <img src="logo.png" width="64" alt="Logo" className="ml-0" /> */}
                <h1 className="text-xl ml-5 text-white font-serif font-pacifico">Sanskriti Chauhan</h1> 
                <div className="flex space-x-8 ml-auto">
                    <Link to="/" className="hover:text-gray-400 text-white text-xl font-serif font-pacifico">Home</Link>
                    <Link to="/about" className="hover:text-gray-400 text-black text-xl font-serif font-pacifico">About</Link>
                    <Link to="/photography" className="hover:text-gray-400 text-black text-xl font-serif font-pacifico">Photography</Link>
                    <Link to="/portfolio" className="hover:text-gray-400 text-black text-xl font-serif font-pacifico">Portfolio</Link>
                </div>
        </nav>
        </header>
    )
}
export default Navbar;
